UPDATE public.destinations SET flag_code = lower(iso_code),
  aliases = ARRAY[lower(iso_code), lower(name_en), lower(name_de)]
WHERE type = 'country';

UPDATE public.destinations d SET aliases = d.aliases || x.extra FROM (VALUES
 ('US', ARRAY['usa','us','amerika','united states of america','vereinigte staaten von amerika']),
 ('GB', ARRAY['uk','england','grossbritannien','großbritannien','great britain','schottland']),
 ('AE', ARRAY['vae','uae','dubai','abu dhabi','emirate']),
 ('TR', ARRAY['turkey','turkiye','istanbul','antalya']),
 ('KR', ARRAY['korea','republic of korea']),
 ('NL', ARRAY['holland']),
 ('CZ', ARRAY['tschechei','czech republic']),
 ('MM', ARRAY['burma','birma']),
 ('CV', ARRAY['kap verde']),
 ('ES', ARRAY['mallorca','kanaren','ibiza']),
 ('PT', ARRAY['madeira','azoren']),
 ('ID', ARRAY['bali']),
 ('TH', ARRAY['bangkok','phuket']),
 ('VA', ARRAY['vatikan']),
 ('MD', ARRAY['moldau','moldawien'])
) AS x(iso, extra) WHERE d.iso_code = x.iso;

UPDATE public.destinations SET sort_order = x.o FROM (VALUES
 ('TR',1),('US',2),('TH',3),('ES',4),('IT',5),('JP',6),('AE',7),('GB',8),('GR',9),('EG',10)
) AS x(iso,o) WHERE iso_code = x.iso;

-- regions
INSERT INTO public.destinations (type, slug, iso_code, name_de, name_en, aliases, continent, sort_order) VALUES
 ('region','europe','EU','Europa','Europe',ARRAY['europe','eu','europa'],'EU',1),
 ('region','asia','AS','Asien','Asia',ARRAY['asia','asien'],'AS',2),
 ('region','north-america','NA','Nordamerika','North America',ARRAY['north america','nordamerika','karibik','caribbean'],'NA',3),
 ('region','south-america','SA','Südamerika','South America',ARRAY['south america','südamerika','lateinamerika','latin america'],'SA',4),
 ('region','africa','AF','Afrika','Africa',ARRAY['africa','afrika'],'AF',5),
 ('region','oceania','OC','Ozeanien','Oceania',ARRAY['oceania','ozeanien','pazifik','pacific'],'OC',6),
 ('global','global','GLOBAL','Weltweit','Global',ARRAY['global','weltweit','world','welt','worldwide'],NULL,7)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.destination_countries (region_id, country_id)
SELECT r.id, c.id FROM public.destinations r JOIN public.destinations c ON c.type = 'country' AND c.continent = r.continent
WHERE r.type = 'region' ON CONFLICT DO NOTHING;

