INSERT INTO public.faqs (category, question, answer, sort_order) VALUES
 ('general','Was ist eine eSIM?','Eine eSIM ist eine digitale SIM-Karte, die fest in deinem Smartphone verbaut ist. Statt eine Plastikkarte einzulegen, lädst du das Profil per QR-Code oder Direktinstallation auf dein Gerät.',1),
 ('general','Ist mein Smartphone eSIM-fähig?','Die meisten aktuellen iPhones ab dem XS/XR, Google Pixel ab dem 3 und viele Samsung-Galaxy-Modelle ab dem S20 unterstützen eSIM. Das Gerät darf zudem keine Netzsperre haben. Prüfe es unter Einstellungen › Mobilfunk bzw. Verbindungen › SIM-Manager.',2),
 ('general','Wann sollte ich die eSIM installieren?','Du kannst die eSIM schon vor der Abreise installieren, solange du eine Internetverbindung hast. Je nach Tarif startet die Laufzeit erst mit der ersten Verbindung im Reiseland.',3),
 ('general','Behalte ich meine normale Telefonnummer?','Ja. Deine bisherige SIM bleibt im Gerät aktiv. Du nutzt die GlobeSIM-eSIM für mobile Daten und kannst über deine gewohnte Nummer weiterhin erreichbar sein.',4),
 ('general','Was passiert, wenn mein Datenvolumen aufgebraucht ist?','Die Datenverbindung über die eSIM endet dann. Wo der Tarif es zulässt, kannst du in deinem Konto Datenvolumen nachbuchen.',5),
 ('general','Kann ich eine eSIM zurückgeben?','Solange die eSIM noch nicht installiert wurde, kannst du dich an unseren Support wenden. Nach der Installation ist eine Erstattung bei digitalen Inhalten in der Regel ausgeschlossen. Details findest du in unserer Widerrufsbelehrung.',6);